/* The Grounded Readings Library, group cath (GWG BLD 798). Written by build-readings.py; edit the data, then build again. */
(window.GGReadingsData = window.GGReadingsData || {})["cath"] = [{"id":"cath-sign-of-the-cross","title":"The Sign of the Cross","by":"Traditional","year":1888,"trad":["catholic"],"denom":["rosary"],"type":"prayer","occasion":["daily","blessing"],"text":"In the name of the Father, and of the Son, and of the Holy Ghost. Amen.","translit":"In nomine Patris, et Filii, et Spiritus Sancti. Amen.","note":"Said while tracing the cross on the body, to open and close every prayer and the Rosary.","voice":"jenny","source":{"name":"Baltimore Catechism No. 2 (1885), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/14552"},"rights":"pd","pd":"Traditional prayer; this English form was in Catholic prayer books by the 1800s; public domain."},{"id":"cath-apostles-creed","title":"The Apostles' Creed","by":"Traditional","year":1891,"trad":["catholic","christian"],"denom":["rosary"],"type":"prayer","occasion":["daily"],"text":"I believe in God, the Father Almighty, Creator of heaven and earth;\nand in Jesus Christ, His only Son, our Lord;\nwho was conceived by the Holy Ghost, born of the Virgin Mary,\nsuffered under Pontius Pilate, was crucified; died, and was buried.\nHe descended into hell; the third day He arose again from the dead;\nHe ascended into heaven, sitteth at the right hand of God, the Father Almighty;\nfrom thence He shall come to judge the living and the dead.\n\nI believe in the Holy Ghost the Holy Catholic Church, the communion of Saints,\nthe forgiveness of sins, the resurrection of the body, and the life everlasting. Amen.","translit":"Credo in Deum, Patrem omnipotentem","note":"Prayed on the crucifix at the start of the Rosary, and a statement of faith for any gathering.","voice":"brian","source":{"name":"Baltimore Catechism No. 2 (1885), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/14552"},"rights":"pd","pd":"Ancient creed; this English form is from the Baltimore Catechism, 1891; public domain."},{"id":"cath-our-father","title":"The Our Father","by":"Traditional","year":1891,"trad":["catholic"],"denom":["rosary"],"type":"prayer","occasion":["daily","comfort"],"text":"Our Father, who art in heaven, hallowed be Thy name:\nThy kingdom come; Thy will be done on earth as it is in heaven.\nGive us this day our daily bread;\nand forgive us our trespasses as we forgive those who trespass against us:\nand lead us not into temptation, but deliver us from evil. Amen.","translit":"Pater noster, qui es in caelis","note":"The Lord's Prayer in its Catholic form, prayed on each large bead of the Rosary.","voice":"jenny","source":{"name":"Baltimore Catechism No. 2 (1885), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/14552"},"rights":"pd","pd":"Matthew 6:9 to 13; this Catholic English form is from the Baltimore Catechism, 1891; public domain."},{"id":"cath-hail-mary","title":"The Hail Mary","by":"Traditional","year":1891,"trad":["catholic"],"denom":["rosary"],"type":"prayer","occasion":["daily","dying","comfort"],"text":"Hail Mary, full of grace! the Lord is with thee:\nblessed art thou amongst women,\nand blessed is the fruit of thy womb, Jesus.\n\nHoly Mary, Mother of God,\npray for us sinners,\nnow and at the hour of our death. Amen.","translit":"Ave Maria, gratia plena, Dominus tecum","note":"Prayed on each of the ten small beads of a Rosary decade, and often at a bedside in the last hours.","voice":"brian","source":{"name":"Baltimore Catechism No. 2 (1885), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/14552"},"rights":"pd","pd":"Luke 1:28 and 1:42 with the traditional closing; this English form is from the Baltimore Catechism, 1891; public domain."},{"id":"cath-glory-be","title":"The Glory Be","by":"Traditional","year":1891,"trad":["catholic","christian"],"denom":["rosary"],"type":"prayer","occasion":["daily","gratitude"],"text":"Glory be to the Father, and to the Son, and to the Holy Ghost.\nAs it was in the beginning, is now, and ever shall be, world without end. Amen.","translit":"Gloria Patri, et Filio, et Spiritui Sancto","note":"Closes each decade of the Rosary and many other prayers, a short song of praise.","voice":"jenny","source":{"name":"Baltimore Catechism No. 2 (1885), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/14552"},"rights":"pd","pd":"Ancient doxology; this English form is from the Baltimore Catechism, 1891; public domain."},{"id":"cath-fatima-prayer","title":"The Fatima Prayer","by":"Traditional","year":1917,"trad":["catholic"],"denom":["rosary"],"type":"prayer","occasion":["daily","forgiveness"],"text":"O my Jesus, forgive us our sins,\nsave us from the fires of hell;\nlead all souls to heaven,\nespecially those most in need of Thy mercy.","note":"Many families add it after the Glory Be at the end of each Rosary decade.","voice":"brian","source":{"name":"Fatima Prayer (1917), Wikipedia overview with history","url":"https://en.wikipedia.org/wiki/Fatima_Prayers"},"rights":"pd","pd":"traditional; standard wording"},{"id":"cath-hail-holy-queen","title":"Hail, Holy Queen","by":"Traditional","year":1888,"trad":["catholic"],"denom":["rosary"],"type":"prayer","occasion":["comfort","grief","evening"],"text":"Hail, holy queen, Mother of mercy,\nour life, our sweetness, and our hope!\nTo thee do we cry, poor banished children of Eve;\nto thee do we send up our sighs, mourning and weeping in this vale of tears.\nTurn then, most gracious advocate, thine eyes of mercy toward us,\nand after this our exile show unto us the blessed fruit of thy womb, Jesus.\nO clement, O loving, O sweet Virgin Mary!\n\nV. Pray for us, O holy Mother of God.\nR. That we may be made worthy of the promises of Christ.","translit":"Salve, Regina, Mater misericordiae","note":"Prayed at the close of the Rosary, and sung at night prayer and at many Catholic funerals.","voice":"jenny","source":{"name":"Bonaventure Hammer, General Catholic Devotions (1909), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/33676"},"rights":"pd","pd":"The Salve Regina, eleventh century; this English form was in Catholic prayer books by the 1800s; public domain."},{"id":"cath-rosary-closing-prayer","title":"The Rosary Prayer","by":"Traditional","year":1888,"trad":["catholic"],"denom":["rosary"],"type":"prayer","occasion":["daily"],"text":"Let us pray.\nO God, whose only begotten Son, by his life, death, and resurrection,\nhas purchased for us the rewards of eternal life,\ngrant we beseech thee, that meditating upon those mysteries,\nin the most holy Rosary of the most blessed Virgin Mary,\nwe may imitate what they contain, and obtain what they promise:\nthrough the same Christ our Lord. Amen.","note":"The closing prayer of the Rosary, after the Hail, Holy Queen.","voice":"brian","source":{"name":"William Gahan, The Complete Manual of Catholic Piety (1844), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/62988"},"rights":"pd","pd":"Collect from the Roman Missal, Feast of the Holy Rosary; this English form was in prayer books by the 1800s; public domain."},{"id":"cath-how-to-pray-the-rosary","title":"How to Pray the Rosary","by":"Grow With Grounded","year":2026,"trad":["catholic"],"denom":["rosary"],"type":"reflection","occasion":["daily","dying","comfort"],"text":"Hold the crucifix, make the Sign of the Cross, and pray the Apostles' Creed.\nOn the first large bead, pray the Our Father.\nOn the next three beads, pray three Hail Marys, for faith, hope, and love.\nThen pray the Glory Be.\n\nName the first mystery and picture it.\nOn the large bead, pray the Our Father.\nOn the ten small beads, pray ten Hail Marys, resting with the mystery.\nClose the decade with the Glory Be, and the Fatima Prayer if your family prays it.\nPray all five decades the same way.\n\nClose with the Hail, Holy Queen, the Rosary Prayer, and the Sign of the Cross.\n\nThe Joyful Mysteries are prayed on Monday and Saturday, the Sorrowful on Tuesday and Friday, the Glorious on Wednesday and Sunday, and the Luminous on Thursday.\n\nAt a bedside, one decade prayed slowly is a whole and loving prayer. A familiar voice and the soft click of the beads bring peace, even while the one you love rests with eyes closed.","note":"A simple guide for a family or a guide praying the Rosary together, at home or at a bedside.","voice":"jenny","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."},{"id":"cath-mystery-joyful-1-annunciation","title":"The First Joyful Mystery: The Annunciation","by":"Douay-Rheims Bible, Luke 1:28, 30 to 31, 38","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["birth","hope"],"text":"And the angel being come in, said unto her: Hail, full of grace, the Lord is with thee: blessed art thou among women.\n\nAnd the angel said to her: Fear not, Mary, for thou hast found grace with God.\nBehold thou shalt conceive in thy womb and shalt bring forth a son: and thou shalt call his name Jesus.\n\nAnd Mary said: Behold the handmaid of the Lord: be it done to me according to thy word. And the angel departed from her.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-joyful-2-visitation","title":"The Second Joyful Mystery: The Visitation","by":"Douay-Rheims Bible, Luke 1:41 to 42, 46 to 47","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["birth","celebration"],"text":"And it came to pass that when Elizabeth heard the salutation of Mary, the infant leaped in her womb. And Elizabeth was filled with the Holy Ghost.\nAnd she cried out with a loud voice and said: Blessed art thou among women and blessed is the fruit of thy womb.\n\nAnd Mary said: My soul doth magnify the Lord.\nAnd my spirit hath rejoiced in God my Saviour.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-joyful-3-nativity","title":"The Third Joyful Mystery: The Nativity","by":"Douay-Rheims Bible, Luke 2:7, 10 to 11","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["birth","season","celebration"],"text":"And she brought forth her first born son and wrapped him up in swaddling clothes and laid him in a manger: because there was no room for them in the inn.\n\nAnd the angel said to them: Fear not; for, behold, I bring you good tidings of great joy that shall be to all the people:\nFor, this day is born to you a Saviour, who is Christ the Lord, in the city of David.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-joyful-4-presentation","title":"The Fourth Joyful Mystery: The Presentation in the Temple","by":"Douay-Rheims Bible, Luke 2:22, 28 to 30","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["birth","blessing","dying"],"text":"And after the days of her purification, according to the law of Moses, were accomplished, they carried him to Jerusalem, to present him to the Lord:\n\nHe also took him into his arms and blessed God and said\nNow thou dost dismiss thy servant, O Lord, according to thy word in peace:\nBecause my eyes have seen thy salvation,","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-joyful-5-finding","title":"The Fifth Joyful Mystery: The Finding in the Temple","by":"Douay-Rheims Bible, Luke 2:46, 49, 51","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["home","daily"],"text":"And it came to pass, that, after three days, they found him in the temple, sitting in the midst of the doctors, hearing them and asking them questions.\n\nAnd he said to them: How is it that you sought me? Did you not know that I must be about my father's business?\n\nAnd he went down with them and came to Nazareth and was subject to them. And his mother kept all these words in her heart.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-luminous-1-baptism","title":"The First Luminous Mystery: The Baptism of the Lord","by":"Douay-Rheims Bible, Matthew 3:16 to 17","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["blessing","birth"],"text":"And Jesus being baptized, forthwith came out of the water: and lo, the heavens were opened to him: and he saw the Spirit of God descending as a dove, and coming upon him.\nAnd behold a voice from heaven saying: This is my beloved Son, in whom I am well pleased.","note":"One of the Luminous Mysteries, named by Saint John Paul II in 2002, read aloud before its decade of the Rosary.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain. The mystery title is a plain name of a Gospel event."},{"id":"cath-mystery-luminous-2-cana","title":"The Second Luminous Mystery: The Wedding at Cana","by":"Douay-Rheims Bible, John 2:1 to 2, 5, 11","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["wedding","celebration"],"text":"And the third day, there was a marriage in Cana of Galilee: and the mother of Jesus was there.\nAnd Jesus also was invited, and his disciples, to the marriage.\n\nHis mother saith to the waiters: Whatsoever he shall say to you, do ye.\n\nThis beginning of miracles did Jesus in Cana of Galilee and manifested his glory. And his disciples believed in him.","note":"One of the Luminous Mysteries, named by Saint John Paul II in 2002, read aloud before its decade of the Rosary.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain. The mystery title is a plain name of a Gospel event."},{"id":"cath-mystery-luminous-3-kingdom","title":"The Third Luminous Mystery: The Proclamation of the Kingdom","by":"Douay-Rheims Bible, Mark 1:14 to 15","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["hope","forgiveness"],"text":"And after that John was delivered up, Jesus came in Galilee, preaching the gospel of the kingdom of God,\nAnd saying: The time is accomplished and the kingdom of God is at hand. Repent and believe the gospel:","note":"One of the Luminous Mysteries, named by Saint John Paul II in 2002, read aloud before its decade of the Rosary.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain. The mystery title is a plain name of a Gospel event."},{"id":"cath-mystery-luminous-4-transfiguration","title":"The Fourth Luminous Mystery: The Transfiguration","by":"Douay-Rheims Bible, Matthew 17:1 to 2, 5","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["hope","nature"],"text":"And after six days Jesus taketh unto him Peter and James, and John his brother, and bringeth them up into a high mountain apart:\nAnd he was transfigured before them. And his face did shine as the sun: and his garments became white as snow.\n\nAnd as he was yet speaking, behold a bright cloud overshadowed them. And lo a voice out of the cloud, saying: This is my beloved Son, in whom I am well pleased: hear ye him.","note":"One of the Luminous Mysteries, named by Saint John Paul II in 2002, read aloud before its decade of the Rosary.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain. The mystery title is a plain name of a Gospel event."},{"id":"cath-mystery-luminous-5-eucharist","title":"The Fifth Luminous Mystery: The Institution of the Eucharist","by":"Douay-Rheims Bible, Luke 22:19 and John 6:51","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["daily","gratitude"],"text":"And taking bread, he gave thanks and brake and gave to them, saying: This is my body, which is given for you. Do this for a commemoration of me.\n\nI am the living bread which came down from heaven.","note":"One of the Luminous Mysteries, named by Saint John Paul II in 2002, read aloud before its decade of the Rosary.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain. The mystery title is a plain name of a Gospel event."},{"id":"cath-mystery-sorrowful-1-agony","title":"The First Sorrowful Mystery: The Agony in the Garden","by":"Douay-Rheims Bible, Luke 22:41 to 43","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["dying","comfort","grief"],"text":"And he was withdrawn away from them a stone's cast. And kneeling down, he prayed.\nSaying: Father, if thou wilt, remove this chalice from me: but yet not my will, but thine be done.\nAnd there appeared to him an angel from heaven, strengthening him. And being in an agony, he prayed the longer.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-sorrowful-2-scourging","title":"The Second Sorrowful Mystery: The Scourging at the Pillar","by":"Douay-Rheims Bible, John 19:1 and Isaias 53:5","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["healing","comfort"],"text":"Then therefore Pilate took Jesus and scourged him.\n\nBut he was wounded for our iniquities, he was bruised for our sins: the chastisement of our peace was upon him, and by his bruises we are healed.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-sorrowful-3-crowning","title":"The Third Sorrowful Mystery: The Crowning with Thorns","by":"Douay-Rheims Bible, Matthew 27:29","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["comfort"],"text":"And platting a crown of thorns, they put it upon his head, and a reed in his right hand. And bowing the knee before him, they mocked him, saying: Hail, King of the Jews.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-sorrowful-4-carrying","title":"The Fourth Sorrowful Mystery: The Carrying of the Cross","by":"Douay-Rheims Bible, John 19:17 and Luke 23:26","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["comfort","grief"],"text":"And bearing his own cross, he went forth to the place which is called Calvary, but in Hebrew Golgotha.\n\nAnd as they led him away, they laid hold of one Simon of Cyrene, coming from the country; and they laid the cross on him to carry after Jesus.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-sorrowful-5-crucifixion","title":"The Fifth Sorrowful Mystery: The Crucifixion","by":"Douay-Rheims Bible, Luke 23:33 to 34, 46","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["dying","forgiveness","funeral"],"text":"And when they were come to the place which is called Calvary, they crucified him there: and the robbers, one on the right hand, and the other on the left.\nAnd Jesus said: Father, forgive them, for they know not what they do. But they, dividing his garments, cast lots.\n\nAnd Jesus crying with a loud voice, said: Father, into thy hands I commend my spirit. And saying this, he gave up the ghost.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-glorious-1-resurrection","title":"The First Glorious Mystery: The Resurrection","by":"Douay-Rheims Bible, Matthew 28:5 to 6","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["hope","funeral","season"],"text":"And the angel answering, said to the women: Fear not you: for I know that you seek Jesus who was crucified.\nHe is not here. For he is risen, as he said. Come, and see the place where the Lord was laid.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-glorious-2-ascension","title":"The Second Glorious Mystery: The Ascension","by":"Douay-Rheims Bible, Luke 24:50 to 51","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["blessing","hope"],"text":"And he led them out as far as Bethania: and lifting up his hands, he blessed them.\nAnd it came to pass, whilst he blessed them, he departed from them and was carried up to heaven.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-glorious-3-pentecost","title":"The Third Glorious Mystery: The Descent of the Holy Spirit","by":"Douay-Rheims Bible, Acts 2:1 to 4","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["blessing","celebration"],"text":"And when the days of the Pentecost were accomplished, they were all together in one place:\nAnd suddenly there came a sound from heaven, as of a mighty wind coming: and it filled the whole house where they were sitting.\nAnd there appeared to them parted tongues, as it were of fire: and it sat upon every one of them.\nAnd they were all filled with the Holy Ghost: and they began to speak with divers tongues, according as the Holy Ghost gave them to speak.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-glorious-4-assumption","title":"The Fourth Glorious Mystery: The Assumption","by":"Douay-Rheims Bible, Canticle of Canticles 2:10 to 12","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["hope","dying","nature"],"text":"Behold my beloved speaketh to me: Arise, make haste, my love, my dove, my beautiful one, and come.\nFor winter is now past, the rain is over and gone.\nThe flowers have appeared in our land, the time of pruning is come: the voice of the turtle is heard in our land:","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-mystery-glorious-5-coronation","title":"The Fifth Glorious Mystery: The Coronation of Mary","by":"Douay-Rheims Bible, Apocalypse 12:1","year":1752,"trad":["catholic"],"denom":["rosary"],"type":"scripture","occasion":["hope","celebration"],"text":"And a great sign appeared in heaven: A woman clothed with the sun, and the moon under her feet, and on her head a crown of twelve stars.","note":"Read aloud before its decade of the Rosary, to give the mind a picture while the beads are prayed.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-memorare","title":"The Memorare","by":"Traditional, attributed to Saint Bernard of Clairvaux","year":1888,"trad":["catholic"],"type":"prayer","occasion":["comfort","hope","grief"],"text":"Remember, O most gracious Virgin Mary,\nthat never was it known that any one who fled to thy protection,\nimplored thy help, and sought thy intercession, was left unaided.\n\nInspired with this confidence, I fly unto thee, O Virgin of virgins, my Mother!\nTo thee I come; before thee I stand, sinful and sorrowful.\nO Mother of the Word incarnate, despise not my petitions,\nbut in thy mercy hear and answer me. Amen.","translit":"Memorare, O piissima Virgo Maria","note":"A prayer of deep trust, prayed in hard waiting and at the bedside.","voice":"brian","source":{"name":"Bonaventure Hammer, General Catholic Devotions (1909), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/33676"},"rights":"pd","pd":"Fifteenth century Latin, popularized by Claude Bernard (died 1641); this English form was in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-saint-michael","title":"Prayer to Saint Michael the Archangel","by":"Pope Leo XIII","year":1909,"trad":["catholic"],"type":"prayer","occasion":["comfort","daily"],"text":"St. Michael the archangel, defend us in battle; be our protection against the malice and snares of the devil. Command him, O God, we humbly beseech Thee, and do thou, O prince of the heavenly hosts, by the divine power, cast into hell Satan and the other evil spirits who roam through the world seeking the ruin of souls. Amen.","translit":"Sancte Michael Archangele, defende nos in proelio","note":"A prayer for protection and courage, long said at the end of Mass and in times of trouble.","voice":"jenny","source":{"name":"Bonaventure Hammer, General Catholic Devotions (1909), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/33676"},"rights":"pd","pd":"prayer of Leo XIII (1886); this English published 1909 (Hammer); US public domain","denom":[]},{"id":"cath-angelus","title":"The Angelus","by":"Traditional","year":1885,"trad":["catholic"],"type":"prayer","occasion":["morning","daily","evening"],"text":"The Angel of the Lord declared unto Mary.\nAnd she conceived of the Holy Ghost.\nHail Mary.\n\nBehold the handmaid of the Lord.\nBe it done unto me according to Thy Word.\nHail Mary.\n\nAnd the Word was made flesh.\nAnd dwelt among us.\nHail Mary.\n\nPray for us, O Holy Mother of God!\nThat we may be made worthy of the promises of Christ.\n\nLet us pray.\nPour forth, we beseech Thee, O Lord, Thy grace into our hearts that we to whom the Incarnation of Christ Thy Son was made known by the message of an angel, may, by His Passion and cross, be brought to the glory of His resurrection, through the same Christ Our Lord. Amen.","translit":"Angelus Domini nuntiavit Mariae","note":"Prayed at six in the morning, noon, and six in the evening, often at the ringing of a bell.","voice":"brian","source":{"name":"Baltimore Catechism No. 3 (1885), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/14553"},"rights":"pd","pd":"traditional prayer; this English published 1885 (Baltimore Catechism); US public domain","denom":[]},{"id":"cath-regina-caeli","title":"Queen of Heaven, Rejoice","by":"Traditional","year":1888,"trad":["catholic"],"type":"prayer","occasion":["season","celebration","hope"],"text":"O Queen of heaven, rejoice, Alleluia.\nFor He Whom thou didst deserve to bear, Alleluia,\nIs risen again, as He said. Alleluia.\nPray for us to God. Alleluia.\n\nV. Rejoice and be glad, O Virgin Mary. Alleluia.\nR. Because Our Lord is truly risen. Alleluia.\n\nLet us pray. O God, Who, by the resurrection of Thy Son, Our Lord Jesus Christ,\nhast been pleased to fill the world with joy: grant, we beseech Thee, that by the Virgin Mary, His Mother,\nwe may receive the joys of eternal life.","translit":"Regina caeli, laetare, alleluia","note":"Prayed in place of the Angelus through the Easter season.","voice":"jenny","source":{"name":"Albert A. Lings, Our Monthly Devotions (1899), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/50739"},"rights":"pd","pd":"The Regina Caeli, twelfth century; this English form was in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-eternal-rest","title":"Eternal Rest","by":"Traditional","year":1888,"trad":["catholic","christian"],"denom":["requiem"],"type":"prayer","occasion":["funeral","grief","dying"],"text":"Eternal rest give unto them, O Lord.\nAnd let perpetual light shine upon them.\nMay they rest in peace. Amen.","translit":"Requiem aeternam dona eis, Domine","note":"Said for the one who has died, at the bedside, the wake, the graveside, and on every anniversary.","voice":"brian","source":{"name":"Baltimore Catechism No. 2 (1885), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/14552"},"rights":"pd","pd":"From the Requiem Mass, 2 Esdras 2:34 to 35; this English form was in prayer books by the 1800s; public domain."},{"id":"cath-anima-christi","title":"Soul of Christ","by":"Traditional","year":1909,"trad":["catholic"],"type":"prayer","occasion":["dying","comfort","healing"],"text":"Soul of Christ, sanctify me!\nBody of Christ, save me!\nBlood of Christ, inebriate me!\nWater from the side of Christ, wash me!\nPassion of Christ, strengthen me!\nO good Jesus, hear me!\nWithin Thy wounds, hide me!\nPermit me not to be separated from Thee!\nFrom the malignant enemy defend me!\nIn the hour of my death call me!\nAnd bid me come to Thee,\nThat, with Thy saints, I may praise Thee\nFor ever and ever. Amen.","translit":"Anima Christi, sanctifica me","note":"The Anima Christi, loved by Saint Ignatius, prayed after Communion and in the last days of life.","voice":"jenny","source":{"name":"Bonaventure Hammer, General Catholic Devotions (1909), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/33676"},"rights":"pd","pd":"traditional prayer; this English published 1909 (Hammer); US public domain","denom":[]},{"id":"cath-act-of-contrition","title":"An Act of Contrition","by":"Traditional","year":1891,"trad":["catholic"],"type":"prayer","occasion":["forgiveness","dying","evening"],"text":"O my God! I am heartily sorry for having offended Thee,\nand I detest all my sins, because I dread the loss of heaven and the pains of hell,\nbut most of all because they offend Thee, my God,\nwho art all-good and deserving of all my love.\nI firmly resolve, with the help of Thy grace,\nto confess my sins, to do penance, and to amend my life.","note":"Prayed in confession, at the close of the day, and by many Catholics in their last hours.","voice":"brian","source":{"name":"Baltimore Catechism No. 2 (1885), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/14552"},"rights":"pd","pd":"From the Baltimore Catechism, 1891; public domain.","denom":[]},{"id":"cath-act-of-faith","title":"An Act of Faith","by":"Traditional","year":1891,"trad":["catholic"],"type":"prayer","occasion":["daily","morning"],"text":"O my God! I firmly believe that Thou art one God in three Divine Persons, Father, Son, and Holy Ghost;\nI believe that Thy Divine Son became man, and died for our sins,\nand that he will come to judge the living and the dead.\nI believe these and all the truths which the Holy Catholic Church teaches,\nbecause Thou hast revealed them, who canst neither deceive nor be deceived.","note":"One of the three acts many Catholics learned as children and pray each morning.","voice":"jenny","source":{"name":"Baltimore Catechism No. 2 (1885), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/14552"},"rights":"pd","pd":"From the Baltimore Catechism, 1891; public domain.","denom":[]},{"id":"cath-act-of-hope","title":"An Act of Hope","by":"Traditional","year":1891,"trad":["catholic"],"type":"prayer","occasion":["hope","dying","comfort"],"text":"O my God! relying on Thy infinite goodness and promises,\nI hope to obtain pardon of my sins, the help of Thy grace,\nand life everlasting, through the merits of Jesus Christ, my Lord and Redeemer.","note":"A short prayer of hope, gentle to pray with someone who is very ill.","voice":"brian","source":{"name":"Baltimore Catechism No. 2 (1885), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/14552"},"rights":"pd","pd":"From the Baltimore Catechism, 1891; public domain.","denom":[]},{"id":"cath-act-of-love","title":"An Act of Love","by":"Traditional","year":1891,"trad":["catholic"],"type":"prayer","occasion":["daily","forgiveness","peace"],"text":"O my God! I love Thee above all things, with my whole heart and soul,\nbecause Thou art all-good and worthy of all love.\nI love my neighbor as myself for the love of Thee.\nI forgive all who have injured me, and ask pardon of all whom I have injured.","note":"A prayer of love and forgiveness, often prayed when a family is making peace.","voice":"jenny","source":{"name":"Baltimore Catechism No. 2 (1885), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/14552"},"rights":"pd","pd":"From the Baltimore Catechism, 1891; public domain.","denom":[]},{"id":"cath-guardian-angel","title":"Angel of God","by":"Traditional","year":1888,"trad":["catholic"],"type":"prayer","occasion":["morning","evening","home"],"text":"Angel of God, my guardian dear,\nTo whom His love commits me here,\nEver this day be at my side,\nTo light and guard, to rule and guide. Amen.","translit":"Angele Dei, qui custos es mei","note":"A child's first prayer in many Catholic homes, said at bedtime and in the morning.","voice":"brian","source":{"name":"Baltimore Catechism No. 2 (1885), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/14552"},"rights":"pd","pd":"Traditional prayer, English form in Catholic prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-come-holy-spirit","title":"Come, Holy Spirit","by":"Traditional","year":1888,"trad":["catholic"],"type":"prayer","occasion":["morning","blessing"],"text":"Come, Holy Ghost, fill the hearts of Thy faithful,\nand enkindle in them the fire of Thy love.\n\nV. Send forth Thy Spirit, and they shall be created.\nR. And Thou shalt renew the face of the earth.\n\nLet us pray. O God, Who didst instruct the hearts of the faithful by the light of Thy Holy Spirit,\ngrant us in the same Holy Spirit to relish what is right, and ever to rejoice in His consolation,\nthrough Christ Our Lord. Amen.","translit":"Veni, Sancte Spiritus","note":"Prayed to begin a meeting, a study, a decision, or a day.","voice":"jenny","source":{"name":"Albert A. Lings, Our Monthly Devotions (1899), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/50739"},"rights":"pd","pd":"Traditional prayer and collect; this English form was in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-morning-offering","title":"The Daily Offering","by":"Traditional, Apostleship of Prayer","year":1909,"trad":["catholic"],"type":"prayer","occasion":["morning","daily"],"text":"O Lord Jesus Christ! In union with that divine intention, with which Thou, whilst on earth, didst give praise to God through Thy most sacred Heart, and which Thou dost still everywhere offer to Him in the Holy Eucharist, even to the consummation of the world; I, in imitation of the most sacred heart of the ever-immaculate Virgin Mary, do most cheerfully offer to Thee, during this entire day, all my thoughts and intentions, all my affections and desires, my words and all my works.","note":"Prayed on waking, to give the whole day to God.","voice":"brian","source":{"name":"Bonaventure Hammer, General Catholic Devotions (1909), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/33676"},"rights":"pd","pd":"traditional prayer; this English published 1909 (Hammer); US public domain","denom":[]},{"id":"cath-grace-before-meals","title":"Grace Before Meals","by":"Traditional","year":1888,"trad":["catholic","christian"],"type":"prayer","occasion":["daily","gratitude","home"],"text":"Bless us, O Lord! and these Thy gifts,\nwhich we are about to receive from Thy bounty,\nthrough Christ our Lord. Amen.","note":"The table grace of countless Catholic homes, lovely at a family meal after a funeral.","voice":"jenny","source":{"name":"Baltimore Catechism No. 2 (1885), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/14552"},"rights":"pd","pd":"Traditional grace; English form in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-grace-after-meals","title":"Grace After Meals","by":"Traditional","year":1888,"trad":["catholic"],"type":"prayer","occasion":["daily","gratitude","grief"],"text":"We give Thee thanks for all Thy benefits, O Almighty God, who livest and reignest forever, and may the souls of the faithful departed through the mercy of God, rest in peace. Amen.","note":"Said after a meal, remembering those who have died.","voice":"brian","source":{"name":"Baltimore Catechism No. 2 (1885), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/14552"},"rights":"pd","pd":"Traditional grace; English form in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-suscipe","title":"Take, Lord, and Receive","by":"Saint Ignatius of Loyola","tr":"Elder Mullan","year":1914,"trad":["catholic"],"denom":["jesuit"],"type":"prayer","occasion":["dying","peace","daily"],"text":"Take, Lord, and receive all my liberty, my memory, my intellect, and all my will,\nall that I have and possess.\nThou gavest it to me: to Thee, Lord, I return it!\nAll is Thine, dispose of it according to all Thy will.\nGive me Thy love and grace, for this is enough for me.","note":"The Suscipe, from the Spiritual Exercises, a prayer of letting go into God's hands.","voice":"jenny","source":{"name":"The Spiritual Exercises of St. Ignatius of Loyola, tr. Elder Mullan (1914), sacred-texts.com","url":"https://sacred-texts.com/chr/seil/seil35.htm"},"rights":"pd","pd":"Written by Ignatius (died 1556); Mullan translation published 1914; public domain."},{"id":"cath-prayer-for-generosity","title":"Prayer for Generosity","by":"Attributed to Saint Ignatius of Loyola","year":1890,"trad":["catholic","christian"],"denom":["jesuit"],"type":"prayer","occasion":["daily","morning"],"text":"Teach us, good Lord, to serve Thee as Thou deservest;\nto give, and not to count the cost;\nto fight, and not to heed the wounds;\nto toil, and not to seek for rest;\nto labour, and not to ask for any reward,\nsave that of knowing that we do Thy will.","note":"A prayer for anyone who serves others, beloved by caregivers and chaplains.","voice":"brian","source":{"name":"A Prayer Book for Soldiers and Sailors (1941), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/50469"},"rights":"pd","pd":"traditional; standard wording; attributed to Saint Ignatius of Loyola"},{"id":"cath-teresa-bookmark","title":"Saint Teresa's Bookmark","by":"Saint Teresa of Avila","tr":"Henry Wadsworth Longfellow","year":1867,"trad":["catholic","all"],"denom":["carmelite"],"type":"prayer","occasion":["comfort","peace","grief"],"text":"Let nothing disturb thee,\nNothing affright thee;\nAll things are passing;\nGod never changeth;\nPatient endurance\nAttaineth to all things;\nWho God possesseth\nIn nothing is wanting;\nAlone God sufficeth.","translit":"Nada te turbe, nada te espante","note":"Found in Teresa's prayer book after her death, a steady word for anxious hours.","voice":"jenny","source":{"name":"The Complete Poetical Works of Henry Wadsworth Longfellow, Project Gutenberg","url":"https://www.gutenberg.org/ebooks/1365"},"rights":"pd","pd":"Written by Teresa (died 1582); Longfellow's translation, Longfellow died 1882; public domain."},{"id":"cath-augustine-restless","title":"Our Heart Is Restless","by":"Saint Augustine of Hippo","tr":"Edward Bouverie Pusey","year":1838,"trad":["catholic","christian","all"],"denom":["augustinian"],"type":"reflection","occasion":["comfort","peace"],"text":"Great art Thou, O Lord, and greatly to be praised;\ngreat is Thy power, and Thy wisdom infinite.\n\nThou awakest us to delight in Thy praise;\nfor Thou madest us for Thyself,\nand our heart is restless, until it repose in Thee.","note":"From the first page of the Confessions, words that have comforted seekers for sixteen hundred years.","voice":"jenny","source":{"name":"The Confessions of Saint Augustine, tr. E. B. Pusey, Project Gutenberg","url":"https://www.gutenberg.org/ebooks/3296"},"rights":"pd","pd":"Written about 400; Pusey translation 1838; public domain."},{"id":"cath-augustine-late-have-i-loved","title":"Too Late Loved I Thee","by":"Saint Augustine of Hippo","tr":"Edward Bouverie Pusey","year":1838,"trad":["catholic","christian"],"denom":["augustinian"],"type":"reflection","occasion":["hope","forgiveness"],"text":"Too late loved I Thee, O Thou Beauty of ancient days, yet ever new!\ntoo late I loved Thee!\nAnd behold, Thou wert within, and I abroad, and there I searched for Thee;\n\nThou wert with me, but I was not with Thee.\n\nThou calledst, and shoutedst, and burstest my deafness.\nThou flashedst, shonest, and scatteredst my blindness.\nThou breathedst odours, and I drew in breath and panted for Thee.\nI tasted, and hunger and thirst.\nThou touchedst me, and I burned for Thy peace.","note":"From Confessions, Book 10, a song of coming home to God at any age.","voice":"brian","source":{"name":"The Confessions of Saint Augustine, tr. E. B. Pusey, Project Gutenberg","url":"https://www.gutenberg.org/ebooks/3296"},"rights":"pd","pd":"Written about 400; Pusey translation 1838; public domain."},{"id":"cath-lead-kindly-light","title":"Lead, Kindly Light","by":"John Henry Newman","year":1833,"trad":["catholic","episcopal","christian","all"],"type":"hymn","occasion":["comfort","hope","funeral"],"text":"Lead, kindly light, amid th' encircling gloom,\nLead Thou me on!\nThe night is dark, and I am far from home;\nLead Thou me on!\nKeep Thou my feet; I do not ask to see\nThe distant scene; one step enough for me.\n\nI was not ever thus, nor prayed that Thou\nShouldst lead me on;\nI loved to choose and see my path; but now\nLead Thou me on!\nI loved the garish day, and, spite of fears,\nPride ruled my will. Remember not past years!\n\nSo long Thy power hath blest me, sure it still\nWill lead me on\nO'er moor and fen, o'er crag and torrent, till\nThe night is gone,\nAnd with the morn those angel faces smile,\nWhich I have loved long since, and lost awhile.","note":"Written at sea in 1833, sung at funerals for its last line about faces loved and lost awhile.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"Written 1833; Newman died 1890; public domain.","denom":[]},{"id":"cath-canticle-of-the-sun","title":"The Canticle of the Sun","by":"Saint Francis of Assisi","tr":"Paschal Robinson","year":1906,"trad":["catholic","christian","nature","all"],"denom":["franciscan"],"type":"prayer","occasion":["nature","gratitude","dying"],"text":"Most high, omnipotent, good Lord,\nPraise, glory and honor and benediction all, are Thine.\nTo Thee alone do they belong, most High,\nAnd there is no man fit to mention Thee.\n\nPraise be to Thee, my Lord, with all Thy creatures,\nEspecially to my worshipful brother sun,\nThe which lights up the day, and through him dost Thou brightness give;\nAnd beautiful is he and radiant with splendor great;\nOf Thee, most High, signification gives.\n\nPraised be my Lord, for sister moon and for the stars,\nIn heaven Thou hast formed them clear and precious and fair.\n\nPraised be my Lord for brother wind\nAnd for the air and clouds and fair and every kind of weather,\nBy the which Thou givest to Thy creatures nourishment.\nPraised be my Lord for sister water,\nThe which is greatly helpful and humble and precious and pure.\n\nPraised be my Lord for brother fire,\nBy the which Thou lightest up the dark.\nAnd fair is he and gay and mighty and strong.\n\nPraised be my Lord for our sister, mother earth,\nThe which sustains and keeps us\nAnd brings forth diverse fruits with grass and flowers bright.\n\nPraised be my Lord for those who for Thy love forgive\nAnd weakness bear and tribulation.\nBlessed those who shall in peace endure,\nFor by Thee, most High, shall they be crowned.\nPraised be my Lord for our sister, the bodily death,\nFrom the which no living man can flee.\nWoe to them who die in mortal sin;\nBlessed those who shall find themselves in Thy most holy will,\nFor the second death shall do them no ill.\n\nPraise ye and bless ye my Lord, and give Him thanks,\nAnd be subject unto Him with great humility.","note":"Francis sang the last verse, welcoming Sister Death, near the end of his life; loved at nature funerals.","voice":"brian","source":{"name":"The Writings of Saint Francis of Assisi, tr. Paschal Robinson (1906), sacred-texts.com","url":"https://sacred-texts.com/chr/wosf/wosf22.htm"},"rights":"pd","pd":"published 1906 (Paschal Robinson, The Writings of Saint Francis of Assisi); US public domain"},{"id":"cath-jesus-the-very-thought","title":"Jesus, the Very Thought of Thee","by":"Attributed to Saint Bernard of Clairvaux","tr":"Edward Caswall","year":1849,"trad":["catholic","christian"],"denom":["cistercian"],"type":"hymn","occasion":["comfort","daily"],"text":"Jesus, the very tho't of thee\nWith sweetness fills my breast;\nBut sweeter far thy face to see,\nAnd in thy presence rest.\n\nNor voice can sing, nor heart can frame,\nNor can the mem'ry find\nA sweeter sound than thy blest name,\nO Savior of mankind!\n\nOh, hope of ev'ry contrite heart!\nOh, joy of all the meek!\nTo those who fall, how kind thou art!\nHow good to those who seek.\n\nAnd those who find\nthee, find a bliss Nor tongue nor pen can show;\nThe love of Jesus, what it is\nNone but his loved ones know.\n\nJesus! our only joy be thou,\nAs thou our prize wilt be;\nJesus! be thou our glory now,\nAnd through eternity.","note":"A gentle hymn of longing and rest, spoken softly at a bedside.","voice":"brian","source":{"name":"The Otterbein Hymnal (1890), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/16455"},"rights":"pd","pd":"Latin Jesu dulcis memoria, twelfth century; Edward Caswall translation 1849, Caswall died 1878; public domain."},{"id":"cath-stabat-mater","title":"At the Cross Her Station Keeping","by":"Traditional, Stabat Mater","tr":"Edward Caswall","year":1849,"trad":["catholic"],"type":"hymn","occasion":["grief","season","comfort"],"text":"At the Cross her station keeping,\nStood the mournful Mother weeping,\nClose to Jesus to the last.\n\nThrough her heart, His sorrow sharing,\nAll His bitter anguish bearing,\nNow at length the sword has passed.\n\nO that blessed one, grief laden,\nBlessed Mother, Blessed Maiden,\nMother of the All-blest one.\n\nHow she stood in desolation\nUpward gazing on the passion\nOf that deathless dying Son.","translit":"Stabat mater dolorosa","note":"The hymn of Mary's grief, sung at the Stations of the Cross; a companion for any parent who grieves a child.","voice":"jenny","source":{"name":"The St. Gregory Hymnal and Catholic Choir Book (1920), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/23673"},"rights":"pd","pd":"Latin, thirteenth century; Edward Caswall translation 1849, Caswall died 1878; public domain.","denom":[]},{"id":"cath-holy-god-we-praise","title":"Holy God, We Praise Thy Name","by":"Traditional, Te Deum","tr":"Clarence A. Walworth","year":1858,"trad":["catholic","christian"],"type":"hymn","occasion":["celebration","gratitude","funeral"],"text":"Holy God, we praise Thy Name,\nLord of all, we bow before Thee;\nAll on earth Thy sceptre claim;\nAll in heav'n above adore Thee,\nInfinite Thy vast domain,\nEverlasting is Thy reign,\n\nHark! The loud celestial hymn,\nAngel choirs above are raising!\nCherubim and Seraphim\nIn unceasing chorus praising;\nFill the Heav'ns with sweet accord;\nHoly, holy, holy Lord!\n\nHoly Father, Holy Son,\nHoly Spirit, Three we name Thee,\nWhile in essence only One,\nUndivided God we claim Thee;\nAnd adoring bend the knee,\nWhile we own the mystery.","note":"A great hymn of praise, often the closing hymn at a Catholic funeral or celebration of life.","voice":"brian","source":{"name":"The St. Gregory Hymnal and Catholic Choir Book (1920), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/23673"},"rights":"pd","pd":"German Grosser Gott, 1771; Clarence Walworth translation 1858, Walworth died 1900; public domain.","denom":[]},{"id":"cath-down-in-adoration","title":"Down in Adoration Falling","by":"Saint Thomas Aquinas","tr":"Edward Caswall","year":1849,"trad":["catholic"],"denom":["dominican"],"type":"hymn","occasion":["daily","blessing"],"text":"Down in adoration falling,\nLo! The sacred Host we hail;\nLo! O'er ancient forms departing,\nNewer rites of grace prevail;\nFaith for all defects supplying,\nWhere the feeble senses fail.\n\nTo the Everlasting Father,\nAnd the Son Who reigns on high,\nWith the Holy Ghost proceeding\nForth from Each eternally,\nBe salvation, honor, blessing,\nMight, and endless majesty. Amen.","translit":"Tantum ergo Sacramentum","note":"The Tantum Ergo, sung at Benediction of the Blessed Sacrament.","voice":"jenny","source":{"name":"William Gahan, The Complete Manual of Catholic Piety (1844), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/62988"},"rights":"pd","pd":"Written by Aquinas, 1264; Edward Caswall translation 1849; public domain."},{"id":"cath-when-morning-gilds","title":"When Morning Gilds the Skies","by":"Traditional German hymn","tr":"Edward Caswall","year":1854,"trad":["catholic","christian"],"type":"hymn","occasion":["morning","gratitude","celebration"],"text":"When morning gilds the skies,\nMy heart, awaking, cries,\nMay Jesus Christ be praised!\n\nBe this, while life is mine,\nMy canticle divine,\nMay Jesus Christ be praised!\nBe this the eternal song\nThrough all the ages on,\nMay Jesus Christ be praised!","note":"A bright morning hymn, joyful for a celebration of life.","voice":"jenny","source":{"name":"Ernest Edwin Ryden, The Story of Our Hymns (1930), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/33998"},"rights":"pd","pd":"German, 1828; Edward Caswall translation 1854; public domain.","denom":[]},{"id":"cath-wideness-in-mercy","title":"There's a Wideness in God's Mercy","by":"Frederick William Faber","year":1854,"trad":["catholic","christian","all"],"denom":["oratorian"],"type":"hymn","occasion":["comfort","forgiveness","funeral"],"text":"There's a wideness in God's mercy\nLike the wideness of the sea;\nThere's a kindness in His justice\nWhich is more than liberty.\n\nThere is welcome for the sinner\nAnd more graces for the good;\nThere is mercy with the Saviour,\nThere is healing in His blood.\n\nFor the love of God is broader\nThan the measure of man's mind,\nAnd the heart of the Eternal\nIs most wonderfully kind.\n\nIf our love were but more simple\nWe should take Him at His word,\nAnd our lives would be all sunshine\nIn the sweetness of the Lord.","note":"A gentle hymn of welcome and mercy, healing for families who worry about a loved one's soul.","voice":"brian","source":{"name":"The Story of the Hymns and Tunes (1907), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/18444"},"rights":"pd","pd":"Written by Faber, 1854; Faber died 1863; public domain."},{"id":"cath-magnificat","title":"The Magnificat","by":"Douay-Rheims Bible, Luke 1:46 to 55","year":1752,"trad":["catholic","christian"],"type":"scripture","occasion":["gratitude","evening","celebration","birth"],"text":"And Mary said: My soul doth magnify the Lord.\nAnd my spirit hath rejoiced in God my Saviour.\nBecause he hath regarded the humility of his handmaid: for behold from henceforth all generations shall call me blessed.\nBecause he that is mighty hath done great things to me: and holy is his name.\nAnd his mercy is from generation unto generations, to them that fear him.\nHe hath shewed might in his arm: he hath scattered the proud in the conceit of their heart.\nHe hath put down the mighty from their seat and hath exalted the humble.\nHe hath filled the hungry with good things: and the rich he hath sent empty away.\nHe hath received Israel his servant, being mindful of his mercy.\nAs he spoke to our fathers: to Abraham and to his seed for ever.","translit":"Magnificat anima mea Dominum","note":"Mary's song of joy, prayed every evening at Vespers and at the birth of a child.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain.","denom":[]},{"id":"cath-sub-tuum","title":"We Fly to Thy Patronage","by":"Traditional, third century","year":1888,"trad":["catholic","orthodox"],"type":"prayer","occasion":["comfort","healing"],"text":"We fly to thy patronage, O holy Mother of God!\nDespise not our petitions in our necessities,\nbut deliver us from all dangers,\nO ever glorious and Blessed Virgin.","translit":"Sub tuum praesidium confugimus","note":"The oldest known prayer to Mary, found on a papyrus from about the third century, shared by East and West.","voice":"brian","source":{"name":"Albert A. Lings, Our Monthly Devotions (1899), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/50739"},"rights":"pd","pd":"Sub tuum praesidium, about 250; English form in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-divine-praises","title":"The Divine Praises","by":"Traditional","year":1921,"trad":["catholic"],"type":"litany","occasion":["gratitude","celebration"],"text":"Blessed be God!\nBlessed be His Holy Name!\nBlessed be Jesus Christ, true God and true Man!\nBlessed be the Name of Jesus;\nBlessed be His most Sacred Heart,\nBlessed be Jesus in the most Holy Sacrament of the Altar!\nBlessed be the great Mother of God, Mary most holy!\nBlessed be her Holy and Immaculate Conception;\nBlessed be the Name of Mary, Virgin and Mother.\nBlessed be Saint Joseph her most chaste spouse.\nBlessed be God in His angels and in His Saints","note":"A litany of blessing, prayed at Benediction; each line is repeated by all.","voice":"brian","source":{"name":"The St. Gregory Hymnal and Catholic Choir Book (1920), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/23673"},"rights":"pd","pd":"Composed by Luigi Felici, 1797, with lines added through 1921; this is the 1921 form; public domain.","denom":[]},{"id":"cath-o-sacrament","title":"O Sacrament Most Holy","by":"Traditional","year":1888,"trad":["catholic"],"type":"prayer","occasion":["gratitude","daily"],"text":"O Sacrament most holy, O Sacrament divine,\nall praise and all thanksgiving be every moment Thine.","note":"A short prayer of thanks, often repeated three times.","voice":"jenny","source":{"name":"The Raccolta, English editions (1880s to 1910), Internet Archive","url":"https://archive.org/search?query=Raccolta+indulgenced+prayers"},"rights":"pd","pd":"traditional; standard wording","denom":[]},{"id":"cath-jesus-mary-joseph","title":"Jesus, Mary, and Joseph","by":"Traditional","year":1888,"trad":["catholic"],"type":"prayer","occasion":["dying","comfort"],"text":"Jesus, Mary, and Joseph, I give you my heart and my soul.\nJesus, Mary, and Joseph, assist me in my last agony.\nJesus, Mary, and Joseph, may I breathe forth my soul in peace with you.","note":"A short prayer for a holy death, easy to whisper again and again at the bedside.","voice":"brian","source":{"name":"Bonaventure Hammer, General Catholic Devotions (1909), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/33676"},"rights":"pd","pd":"Traditional prayer from the Raccolta, English editions from the 1800s; public domain.","denom":[]},{"id":"cath-prayer-before-crucifix","title":"Prayer Before a Crucifix","by":"Traditional","year":1888,"trad":["catholic"],"type":"prayer","occasion":["comfort","forgiveness","season"],"text":"Look down upon me, good and gentle Jesus,\nwhile before Thy face I humbly kneel,\nand with burning soul pray and beseech Thee\nto fix deep in my heart lively sentiments of faith, hope, and charity,\ntrue contrition for my sins, and a firm purpose of amendment;\nwhile I contemplate with great love and tender pity\nThy five wounds,\npondering over them within me,\nand calling to mind the words which David Thy prophet said of Thee, my Jesus:\nThey pierced my hands and my feet; they numbered all my bones.","translit":"En ego, O bone et dulcissime Iesu","note":"The En ego, prayed after Communion and before a crucifix, especially in Lent.","voice":"jenny","source":{"name":"Bonaventure Hammer, General Catholic Devotions (1909), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/33676"},"rights":"pd","pd":"Traditional Latin En ego; English form in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-veni-creator","title":"Come, Holy Ghost, Our Souls Inspire","by":"Traditional, Veni Creator Spiritus","tr":"John Cosin","year":1662,"trad":["catholic","episcopal","christian"],"type":"hymn","occasion":["blessing","wedding"],"text":"Come, Holy Ghost, our souls inspire,\nAnd lighten with celestial fire.\nThou the anointing Spirit art,\nWho dost thy sevenfold gifts impart.\n\nThy blessed unction from above,\nIs comfort, life, and fire of love.\nEnable with perpetual light\nThe dulness of our blinded sight.\n\nAnoint and cheer our soiled face\nWith the abundance of thy grace.\nKeep far our foes, give peace at home;\nWhere thou art guide, no ill can come.\n\nTeach us to know the Father, Son,\nAnd thee, of both, to be but One;\nThat, through the ages all along,\nThis may be our endless song:\nPraise to thy eternal merit,\nFather, Son, and Holy Spirit.","translit":"Veni, Creator Spiritus","note":"The ancient hymn to the Holy Spirit, sung at ordinations, confirmations, and some weddings.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States), Charles Wohlers's text","url":"http://justus.anglican.org/resources/bcp/1928/BCP_1928.htm"},"rights":"pd","pd":"Latin, ninth century; John Cosin translation 1627, printed in the Book of Common Prayer 1662; public domain.","denom":[]},{"id":"cath-litany-of-loreto","title":"The Litany of Loreto","by":"Traditional","year":1909,"trad":["catholic"],"type":"litany","occasion":["comfort","healing","dying"],"text":"Lord, have mercy on us,\nChrist, have mercy on us.\nLord, have mercy on us,\nChrist, hear us.\nChrist, graciously hear us.\nGod the Father of heaven, have mercy on us.\nGod the Son, Redeemer of the world, have mercy on us.\nGod the Holy Ghost, have mercy on us.\nHoly Trinity, one God, have mercy on us.\nHoly Mary, pray for us.\nHoly Mother of God, pray for us.\nHoly Virgin of virgins, pray for us.\nMother of Christ, pray for us.\nMother of divine grace, pray for us.\nMother most pure, pray for us.\nMother most chaste, pray for us.\nMother inviolate, pray for us.\nMother undefiled, pray for us.\nMother most amiable, pray for us.\nMother most admirable, pray for us.\nMother of good counsel, pray for us.\nMother of our Creator, pray for us.\nMother of our Redeemer, pray for us.\nVirgin most prudent, pray for us.\nVirgin most venerable, pray for us.\nVirgin most renowned, pray for us.\nVirgin most powerful, pray for us.\nVirgin most merciful, pray for us.\nVirgin most faithful, pray for us.\nMirror of justice, pray for us.\nSeat of wisdom, pray for us.\nCause of our joy, pray for us.\nSpiritual vessel, pray for us.\nVessel of honor, pray for us.\nSingular vessel of devotion, pray for us.\nMystical rose, pray for us.\nTower of David, pray for us.\nTower of ivory, pray for us.\nHouse of gold, pray for us.\nArk of the covenant, pray for us.\nGate of heaven, pray for us.\nMorning star, pray for us.\nHealth of the sick, pray for us.\nRefuge of sinners, pray for us.\nComforter of the afflicted, pray for us.\nHelp of Christians, pray for us.\nQueen of angels, pray for us.\nQueen of patriarchs, pray for us.\nQueen of prophets, pray for us.\nQueen of apostles, pray for us.\nQueen of martyrs, pray for us.\nQueen of confessors, pray for us.\nQueen of virgins, pray for us.\nQueen of all saints, pray for us.\nQueen conceived without original sin, pray for us.\nQueen of the most holy rosary, pray for us.\nLamb of God, who takest away the sins of the world: Spare us, O Lord.\nLamb of God, who takest away the sins of the world: Graciously hear us, O Lord.\nLamb of God, who takest away the sins of the world: Have mercy on us, O Lord.","note":"From the Litany of the Blessed Virgin Mary; Health of the sick and Comforter of the afflicted are well loved at a bedside.","voice":"jenny","source":{"name":"Bonaventure Hammer, General Catholic Devotions (1909), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/33676"},"rights":"pd","pd":"traditional litany; this English published 1909 (Hammer); US public domain","denom":[]},{"id":"cath-litany-sacred-heart","title":"From the Litany of the Sacred Heart","by":"Traditional","year":1899,"trad":["catholic"],"type":"litany","occasion":["comfort","dying","peace"],"text":"Heart of Jesus, full of goodness and love, have mercy on us.\nHeart of Jesus, patient and most merciful, have mercy on us.\nHeart of Jesus, source of all consolation, have mercy on us.\nHeart of Jesus, our life and resurrection, have mercy on us.\nHeart of Jesus, our peace and reconciliation, have mercy on us.\nHeart of Jesus, salvation of those who trust in thee, have mercy on us.\nHeart of Jesus, hope of those who die in Thee, have mercy on us.\nHeart of Jesus, delight of all the saints, have mercy on us.\n\nV. Jesus, meek and humble of Heart:\nR. Make our hearts like unto Thine.","note":"A few of the litany's lines, chosen for the bedside; hope of those who die in Thee comforts many families.","voice":"jenny","source":{"name":"Bonaventure Hammer, General Catholic Devotions (1909), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/33676"},"rights":"pd","pd":"Approved for the whole Church by Pope Leo XIII in 1899; English form in prayer books; public domain. A selection.","denom":[]},{"id":"cath-in-paradisum","title":"May the Angels Lead You into Paradise","by":"Traditional, In Paradisum","year":1888,"trad":["catholic","christian"],"denom":["requiem"],"type":"prayer","occasion":["funeral","dying","grief"],"text":"May the angels lead thee into paradise;\nmay the martyrs receive thee at thy coming,\nand lead thee into the holy city Jerusalem.\nMay the choir of angels receive thee,\nand with Lazarus, who once was poor,\nmayest thou have eternal rest.","translit":"In paradisum deducant te angeli","note":"Sung or said as the body is carried from the church at the end of a Catholic funeral.","voice":"brian","source":{"name":"A Manual of Prayers for the Use of the Catholic Laity (1888), Internet Archive","url":"https://archive.org/search?query=%22Manual+of+Prayers+for+the+Use+of+the+Catholic+Laity%22"},"rights":"pd","pd":"traditional; standard wording"},{"id":"cath-subvenite","title":"Come to Assist Him, You Saints of God","by":"Traditional, Subvenite","year":1888,"trad":["catholic"],"denom":["requiem"],"type":"prayer","occasion":["dying","funeral"],"text":"Come to his assistance, ye saints of God;\ncome forth to meet him, ye angels of the Lord:\nReceiving his soul: Offering it in the sight of the Most High.","translit":"Subvenite, Sancti Dei","note":"Prayed right after death, at the bedside, and at the final commendation of a funeral; say her as fits.","voice":"jenny","source":{"name":"John Henry Newman, The Dream of Gerontius, illustrated edition notes, Project Gutenberg","url":"https://www.gutenberg.org/ebooks/48927"},"rights":"pd","pd":"From the Latin rite for the dead, early medieval; English form in prayer books by the 1800s; public domain."},{"id":"cath-proficiscere","title":"Depart, O Christian Soul","by":"Traditional, Proficiscere","year":1844,"trad":["catholic"],"denom":["requiem"],"type":"prayer","occasion":["dying"],"text":"Depart then, O Christian soul, out of this miserable world, in the name of God the Father Almighty, who created thee; in the name of Jesus Christ, the Son of the living God, who suffered for thee; in the name of the Holy Ghost, who sanctified thee; in the name of the angels, archangels, thrones, dominations, cherubim, and seraphim; in the name of the patriarchs and prophets, of the holy apostles, and evangelists, of the holy martyrs and confessors, of the holy monks and hermits, of the holy virgins, and of all the saints of God: let thy place be this day in peace, and thy abode in holy Sion: through Christ our Lord. Amen.","translit":"Proficiscere, anima christiana, de hoc mundo","note":"The Church's ancient blessing for the moment of death, said as the last breaths come.","voice":"brian","source":{"name":"William Gahan, The Complete Manual of Catholic Piety (1844), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/62988"},"rights":"pd","pd":"traditional prayer; this English published 1844 (Gahan); US public domain"},{"id":"cath-gerontius-go-forth","title":"Go Forth upon Thy Journey","by":"John Henry Newman","year":1865,"trad":["catholic","christian"],"type":"poem","occasion":["dying"],"text":"Proficiscere, anima Christiana, de hoc mundo!\nGo forth upon thy journey, Christian soul!\nGo from this world! Go, in the name of God,\nThe omnipotent Father, who created thee!\nGo, in the name of Jesus Christ, our Lord,\nSon of the living God, who bled for thee!\nGo, in the Name of the Holy Spirit, who\nHath been poured out on thee! Go, in the name\nOf Angels and Archangels; in the name\nOf Thrones and Dominations; in the name\nOf Princedoms and of Powers; and in the name\nOf Cherubim and Seraphim, go forth!","note":"The priest's words at the deathbed in The Dream of Gerontius, the old prayer set as poetry.","voice":"jenny","source":{"name":"John Henry Newman, The Dream of Gerontius (1865), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/48927"},"rights":"pd","pd":"Published 1865; Newman died 1890; public domain.","denom":[]},{"id":"cath-gerontius-softly","title":"Softly and Gently","by":"John Henry Newman","year":1865,"trad":["catholic","christian","all"],"type":"poem","occasion":["dying","funeral","grief"],"text":"Softly and gently, dearly-ransomed soul,\nIn my most loving arms I now enfold thee,\nAnd, o'er the penal waters, as they roll,\nI poise thee, and I lower thee, and hold thee.\n\nAnd carefully I dip thee in the lake,\nAnd thou, without a sob or a resistance,\nDost through the flood thy rapid passage take,\nSinking deep, deeper into the dim distance.\n\nAngels, to whom the willing task is given,\nShall tend, and nurse, and lull thee, as thou liest;\nAnd Masses on the earth, and prayers in heaven,\nShall aid thee at the Throne of the Most Highest.\n\nFarewell, but not for ever! brother dear,\nBe brave and patient on thy bed of sorrow;\nSwiftly shall pass thy night of trial here,\nAnd I will come and wake thee on the morrow.","note":"The guardian angel's farewell from The Dream of Gerontius, tender at a vigil or a funeral; say sister dear as fits.","voice":"brian","source":{"name":"John Henry Newman, The Dream of Gerontius (1865), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/48927"},"rights":"pd","pd":"Published 1865; Newman died 1890; public domain.","denom":[]},{"id":"cath-dies-irae","title":"From the Dies Irae","by":"Traditional, attributed to Thomas of Celano","tr":"William Josiah Irons","year":1849,"trad":["catholic"],"denom":["requiem"],"type":"hymn","occasion":["funeral","forgiveness"],"text":"Think, good Jesus, my salvation\nCost thy wondrous Incarnation;\nLeave me not to reprobation!\n\nFaint and weary, thou hast sought me,\nOn the cross of suffering bought me.\nShall such grace be vainly brought me?\n\nThou the sinful woman savedst;\nThou the dying thief forgavest;\nAnd to me a hope vouchsafest.\n\nLord, all pitying, Jesus blest,\nGrant them thine eternal rest. Amen.","translit":"Pie Iesu Domine, dona eis requiem","note":"The mercy verses of the old Requiem sequence, a plea for grace sung at funerals for centuries.","voice":"jenny","source":{"name":"The Hymnal of the Protestant Episcopal Church (1916; 1920 printing), Christian Classics Ethereal Library","url":"https://ccel.org/ccel/anonymous/eh1916"},"rights":"pd","pd":"Latin hymn; tr. William J. Irons (1849), as printed in The Hymnal (1916); US public domain"},{"id":"cath-de-profundis","title":"Out of the Depths (Psalm 129)","by":"Douay-Rheims Bible, Psalm 129","year":1752,"trad":["catholic","christian"],"denom":["requiem"],"type":"scripture","occasion":["grief","funeral","forgiveness","hope"],"text":"Out of the depths I have cried to thee, O Lord:\nLord, hear my voice. Let thy ears be attentive to the voice of my supplication.\nIf thou, O Lord, wilt mark iniquities: Lord, who shall stand it.\nFor with thee there is merciful forgiveness: and by reason of thy law, I have waited for thee, O Lord. My soul hath relied on his word:\nmy soul hath hoped in the Lord.\nFrom the morning watch even until night, let Israel hope in the Lord.\nBecause with the Lord there is mercy: and with him plentiful redemption.\nAnd he shall redeem Israel from all his iniquities.","translit":"De profundis clamavi ad te, Domine","note":"The De Profundis, the Church's psalm for the dead, prayed at wakes and on anniversaries (Psalm 130 in most Bibles).","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain."},{"id":"cath-for-the-faithful-departed","title":"For All the Faithful Departed","by":"Traditional, Roman Missal","year":1888,"trad":["catholic"],"denom":["requiem"],"type":"prayer","occasion":["grief","funeral"],"text":"O God, the Creator and Redeemer of all the faithful,\ngrant to the souls of Thy servants departed the remission of all their sins,\nthat through pious supplications they may obtain that pardon which they have always desired;\nWho livest and reignest with God the Father in the unity of the Holy Ghost, God, world without end. Amen.","translit":"Fidelium, Deus, omnium Conditor et Redemptor","note":"The collect for All Souls, said on November 2 and whenever a family remembers its dead.","voice":"jenny","source":{"name":"Albert A. Lings, Our Monthly Devotions (1899), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/50739"},"rights":"pd","pd":"Collect Fidelium Deus from the Roman Missal; English form in prayer books by the 1800s; public domain."},{"id":"cath-holy-and-wholesome","title":"A Holy and Wholesome Thought","by":"Douay-Rheims Bible, 2 Machabees 12:46","year":1752,"trad":["catholic"],"type":"scripture","occasion":["grief","funeral"],"text":"It is therefore a holy and wholesome thought to pray for the dead, that they may be loosed from sins.","note":"The verse behind the Catholic custom of praying for those who have died.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain.","denom":[]},{"id":"cath-wisdom-3","title":"The Souls of the Just (Wisdom 3)","by":"Douay-Rheims Bible, Wisdom 3:1 to 3, 9","year":1752,"trad":["catholic","episcopal","orthodox"],"type":"scripture","occasion":["funeral","grief","hope"],"text":"But the souls of the just are in the hand of God, and the torment of death shall not touch them.\nIn the sight of the unwise they seemed to die: and their departure was taken for misery:\nAnd their going away from us, for utter destruction: but they are in peace.\n\nThey that trust in him shall understand the truth: and they that are faithful in love, shall rest in him: for grace and peace are to his elect.","note":"One of the best loved readings at Catholic funerals.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain.","denom":[]},{"id":"cath-john-11","title":"I Am the Resurrection (John 11)","by":"Douay-Rheims Bible, John 11:25 to 26","year":1752,"trad":["catholic"],"type":"scripture","occasion":["funeral","hope","dying"],"text":"Jesus said to her: I am the resurrection and the life: he that believeth in me, although he be dead, shall live:\nAnd every one that liveth and believeth in me shall not die for ever. Believest thou this?","note":"Spoken to Martha at her brother's grave, and read at almost every Christian funeral.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain.","denom":[]},{"id":"cath-beatitudes","title":"The Beatitudes","by":"Douay-Rheims Bible, Matthew 5:3 to 10","year":1752,"trad":["catholic","christian"],"type":"scripture","occasion":["funeral","comfort","grief"],"text":"Blessed are the poor in spirit: for theirs is the kingdom of heaven.\nBlessed are the meek: for they shall possess the land.\nBlessed are they that mourn: for they shall be comforted.\nBlessed are they that hunger and thirst after justice: for they shall have their fill.\nBlessed are the merciful: for they shall obtain mercy.\nBlessed are the clean of heart: they shall see God.\nBlessed are the peacemakers: for they shall be called the children of God.\nBlessed are they that suffer persecution for justice' sake: for theirs is the kingdom of heaven.","note":"A favorite funeral Gospel, honoring a life lived with mercy and peace.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain.","denom":[]},{"id":"cath-charity-1-cor-13","title":"Charity Is Patient (1 Corinthians 13)","by":"Douay-Rheims Bible, 1 Corinthians 13:4 to 8, 13","year":1752,"trad":["catholic"],"type":"scripture","occasion":["wedding","funeral"],"text":"Charity is patient, is kind: charity envieth not, dealeth not perversely, is not puffed up,\nIs not ambitious, seeketh not her own, is not provoked to anger, thinketh no evil:\nRejoiceth not in iniquity, but rejoiceth with the truth:\nBeareth all things, believeth all things, hopeth all things, endureth all things.\nCharity never falleth away: whether prophecies shall be made void or tongues shall cease or knowledge shall be destroyed.\n\nAnd now there remain faith, hope, and charity, these three: but the greatest of these is charity.","note":"The love chapter in the Catholic Douay wording, read at weddings and at funerals of a loving life.","voice":"jenny","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain.","denom":[]},{"id":"cath-ruth-whither","title":"Whither Thou Shalt Go (Ruth 1)","by":"Douay-Rheims Bible, Ruth 1:16 to 17","year":1752,"trad":["catholic"],"type":"scripture","occasion":["wedding","home"],"text":"She answered: Be not against me, to desire that I should leave thee and depart: for whithersoever thou shalt go, I will go: and where thou shalt dwell, I also will dwell. Thy people shall be my people, and thy God my God.\nThe land that shall receive thee dying, in the same will I die: and there will I be buried. The Lord do so and so to me, and add more also, if aught but death part me and thee.","note":"Ruth's promise to Naomi, read at weddings and to honor lifelong loyalty.","voice":"brian","source":{"name":"Douay-Rheims Bible, Challoner revision (1752), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/8300"},"rights":"pd","pd":"Douay-Rheims translation 1582 to 1610, Challoner revision 1752; public domain.","denom":[]},{"id":"cath-works-of-mercy","title":"The Works of Mercy","by":"Traditional","year":1891,"trad":["catholic","christian"],"type":"reflection","occasion":["funeral","daily"],"text":"The chief corporal works of mercy are seven: To feed the hungry, to give drink to the thirsty, to clothe the naked, to ransom the captive, to harbor the harborless, to visit the sick, and to bury the dead.\n\nThe chief spiritual works of mercy are seven: To admonish the sinner, to instruct the ignorant, to counsel the doubtful, to comfort the sorrowful, to bear wrongs patiently, to forgive all injuries, and to pray for the living and the dead.","note":"A way to honor a life spent serving others, read at a funeral or a volunteer's memorial.","voice":"jenny","source":{"name":"Baltimore Catechism No. 2 (1885), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/14552"},"rights":"pd","pd":"From the Baltimore Catechism, 1891, rooted in Matthew 25; public domain.","denom":[]},{"id":"cath-stations-of-the-cross","title":"The Stations of the Cross","by":"Traditional","year":1909,"trad":["catholic"],"type":"litany","occasion":["season","comfort","grief"],"text":"We adore Thee, O Christ, and praise Thee: Because by Thy holy cross Thou hast redeemed the world.\n\nFirst Station: Jesus is condemned to death.\nSecond Station: Jesus carries His Cross.\nThird Station: Jesus falls the first time.\nFourth Station: Jesus meets His afflicted Mother.\nFifth Station: Simon of Cyrene helps Jesus to carry the Cross.\nSixth Station: Veronica wipes the face of Jesus.\nSeventh Station: Jesus falls the second time.\nEighth Station: The daughters of Jerusalem weep over Jesus.\nNinth Station: Jesus falls the third time.\nTenth Station: Jesus is stripped of His garments.\nEleventh Station: Jesus is nailed to the Cross.\nTwelfth Station: Jesus is raised upon the Cross, and dies.\nThirteenth Station: Jesus is taken down from the Cross, and placed in the arms of His Mother.\nFourteenth Station: Jesus is laid in the sepulcher.\n\nWe adore Thee, O Christ, and praise Thee: Because by Thy holy cross Thou hast redeemed the world.","translit":"Adoramus te, Christe, et benedicimus tibi","note":"Walked in church on the Fridays of Lent; the versicle is said at each station. Many who suffer find company in it.","voice":"brian","source":{"name":"Bonaventure Hammer, General Catholic Devotions (1909), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/33676"},"rights":"pd","pd":"traditional devotion; this English published 1909 (Hammer); US public domain","denom":[]},{"id":"cath-priestly-blessing","title":"May Almighty God Bless You","by":"Traditional","year":1888,"trad":["catholic","christian"],"type":"blessing","occasion":["blessing","funeral","wedding"],"text":"May the blessing of Almighty God, the Father, and the Son, and the Holy Ghost, descend upon us, and dwell with us for evermore. Amen.","translit":"Benedicat vos omnipotens Deus","note":"A closing blessing for a gathering, a home, or a family leaving the graveside.","voice":"jenny","source":{"name":"William Gahan, The Complete Manual of Catholic Piety (1844), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/62988"},"rights":"pd","pd":"Traditional blessing; English form in prayer books by the 1800s; public domain.","denom":[]},{"id":"cath-vigil-with-the-rosary","title":"A Blessing for a Rosary Vigil","by":"Grow With Grounded","year":2026,"trad":["catholic"],"denom":["rosary"],"type":"blessing","occasion":["dying","comfort"],"text":"Bead by bead, we keep watch with you.\nMary, who stood near her Son to the last, stands near you now.\nEvery Hail Mary is a hand held.\nRest in the love that surrounds you.","note":"Grounded words to open or close a family's Rosary at the bedside.","voice":"brian","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."},{"id":"cath-blessing-for-a-catholic-home","title":"A Blessing for a Catholic Home","by":"Grow With Grounded","year":2026,"trad":["catholic"],"type":"blessing","occasion":["home","blessing"],"text":"Holy Family of Nazareth, make this house a home like yours.\nMay its table be full of good food and laughter,\nits doors open to friends and strangers,\nits nights full of peace,\nand its rooms full of the quiet presence of God.","note":"Grounded words for a house blessing, alongside holy water and the family's own prayers.","voice":"jenny","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words.","denom":[]},{"id":"cath-o-heavenly-king","title":"O Heavenly King","by":"Traditional","year":1922,"trad":["orthodox"],"denom":["eastern"],"type":"prayer","occasion":["morning","blessing","daily"],"text":"O heavenly King, the Comforter, Spirit of Truth,\nwho art in all places and fillest all things;\nTreasury of good things and Giver of life:\nCome and take up thine abode in us, and cleanse us from every stain;\nand save our souls, O Good One.","translit":"Vasilefs ouranie, Paraklite","note":"The prayer to the Holy Spirit that opens nearly every Orthodox service and the day's prayers.","voice":"jenny","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (revised edition, 1922), Internet Archive","url":"https://archive.org/details/ServiceBookOfHolyOrthodoxChurchByHapgood"},"rights":"pd","pd":"published 1922 (Hapgood, revised edition; first edition 1906); Hapgood died 1928"},{"id":"cath-trisagion","title":"The Trisagion","by":"Traditional","year":1922,"trad":["orthodox","catholic","oriental"],"denom":["eastern"],"type":"chant","occasion":["daily","funeral","dying"],"text":"O Holy God, Holy Mighty, Holy Immortal One, have mercy upon us.\n\nGlory to the Father, and to the Son, and to the Holy Spirit, now, and ever, and unto ages of ages. Amen.\n\nO all-holy Trinity, have mercy upon us. O Lord, wash away our sins. O Master, pardon our transgressions. O Holy One, visit and heal our infirmities, for thy Name's sake.\n\nLord, have mercy.","translit":"Agios o Theos, Agios Ischyros, Agios Athanatos, eleison imas","note":"The thrice holy hymn, sung in the services of every Eastern church, and the heart of the short memorial at the grave.","voice":"brian","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (revised edition, 1922), Internet Archive","url":"https://archive.org/details/ServiceBookOfHolyOrthodoxChurchByHapgood"},"rights":"pd","pd":"published 1922 (Hapgood, revised edition; first edition 1906); Hapgood died 1928"},{"id":"cath-christ-is-risen","title":"Christ Is Risen","by":"Traditional, Paschal Troparion","year":1922,"trad":["orthodox","oriental","all"],"denom":["eastern"],"type":"chant","occasion":["season","hope","funeral","celebration"],"text":"Christ is risen from the dead,\ntrampling down Death by death,\nand upon those in the tomb bestowing life.","translit":"Christos anesti ek nekron","note":"The Easter hymn, sung over and over for forty days and at Orthodox funerals in the Easter season.","voice":"jenny","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (revised edition, 1922), Internet Archive","url":"https://archive.org/details/ServiceBookOfHolyOrthodoxChurchByHapgood"},"rights":"pd","pd":"published 1922 (Hapgood, revised edition; first edition 1906); Hapgood died 1928"},{"id":"cath-prayer-of-saint-ephrem","title":"The Prayer of Saint Ephrem","by":"Saint Ephrem the Syrian","year":1922,"trad":["orthodox","oriental"],"denom":["eastern","syriac"],"type":"prayer","occasion":["season","forgiveness","daily"],"text":"O Lord and Master of my life, grant not unto me a spirit of slothfulness, of discouragement, of lust of power, of vain babbling.\n\nBut vouchsafe unto thy servant the spirit of continence, of meekness, of patience, and of love.\n\nYea, O Lord and King, grant that I may perceive my own transgressions, and judge not my brother. For blessed art thou unto ages of ages. Amen.","note":"Prayed with bows throughout Great Lent; a whole spiritual life in three lines.","voice":"jenny","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (revised edition, 1922), Internet Archive","url":"https://archive.org/details/ServiceBookOfHolyOrthodoxChurchByHapgood"},"rights":"pd","pd":"published 1922 (Hapgood, revised edition; first edition 1906); Hapgood died 1928"},{"id":"cath-glory-for-all-things","title":"Glory to God for All Things","by":"Saint John Chrysostom","year":1906,"trad":["orthodox","all"],"denom":["eastern"],"type":"reflection","occasion":["dying","gratitude"],"text":"Glory to God for all things.","translit":"Doxa to Theo panton eneken","note":"The last words of Saint John Chrysostom as he died in exile in 407; a whole life of gratitude in five words.","voice":"brian","source":{"name":"Palladius, Dialogue on the Life of St. John Chrysostom, Internet Archive","url":"https://archive.org/search?query=Palladius+dialogue+life+of+St.+John+Chrysostom"},"rights":"pd","pd":"traditional; standard wording"},{"id":"cath-axion-estin","title":"Meet Is It in Very Truth","by":"Traditional","year":1922,"trad":["orthodox"],"denom":["eastern"],"type":"chant","occasion":["daily","gratitude"],"text":"Meet is it in very truth to bless thee, O Birth-giver of God, ever-blessed and all-undefiled One, and the Mother of our God.\n\nMore honourable than the Cherubim, and beyond compare more glorious than the Seraphim, thou who without corruption barest God the Word, true Birth-giver of God, we magnify thee.","translit":"Axion estin os alithos","note":"The hymn to the Mother of God sung at the Divine Liturgy and at the close of many prayers.","voice":"jenny","source":{"name":"Isabel F. Hapgood, Service Book of the Holy Orthodox-Catholic Apostolic Church (revised edition, 1922), Internet Archive","url":"https://archive.org/details/ServiceBookOfHolyOrthodoxChurchByHapgood"},"rights":"pd","pd":"published 1922 (Hapgood, revised edition; first edition 1906); Hapgood died 1928"},{"id":"cath-eyes-of-all","title":"The Eyes of All (Grace)","by":"King James Version, Psalm 145:15 to 16","year":1611,"trad":["orthodox","christian"],"denom":["eastern"],"type":"scripture","occasion":["daily","gratitude","home"],"text":"The eyes of all wait upon thee; and thou givest them their meat in due season.\nThou openest thine hand, and satisfiest the desire of every living thing.","note":"The verse many Orthodox and Anglican families sing or say as grace before meals.","voice":"jenny","source":{"name":"King James Bible (1611), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/10"},"rights":"pd","pd":"King James Version, 1611; public domain in the United States."},{"id":"cath-psalm-104-vespers","title":"O Lord My God, Thou Art Very Great (Psalm 104)","by":"King James Version, Psalm 104:1 to 2, 10 to 12, 24, 33","year":1611,"trad":["orthodox","christian","nature"],"denom":["eastern"],"type":"scripture","occasion":["nature","evening","gratitude"],"text":"Bless the Lord, O my soul. O Lord my God, thou art very great; thou art clothed with honour and majesty.\nWho coverest thyself with light as with a garment: who stretchest out the heavens like a curtain:\n\nHe sendeth the springs into the valleys, which run among the hills.\nThey give drink to every beast of the field: the wild asses quench their thirst.\nBy them shall the fowls of the heaven have their habitation, which sing among the branches.\n\nO Lord, how manifold are thy works! in wisdom hast thou made them all: the earth is full of thy riches.\n\nI will sing unto the Lord as long as I live: I will sing praise to my God while I have my being.","note":"The creation psalm that opens Orthodox Vespers every evening; lovely for a nature lover.","voice":"brian","source":{"name":"King James Bible (1611), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/10"},"rights":"pd","pd":"King James Version, 1611; public domain in the United States."},{"id":"cath-phos-hilaron","title":"Hail, Gladdening Light","by":"Traditional Greek hymn, third century","tr":"John Keble","year":1834,"trad":["orthodox","episcopal","christian"],"denom":["eastern"],"type":"hymn","occasion":["evening","peace"],"text":"Hail! gladdening Light of His pure glory poured,\nWho is the immortal Father, heavenly, blest,\nHoliest of Holies, Jesus Christ our Lord!\n\nNow we are come to the sun’s hour of rest,\nThe lights of evening round us shine,\nWe hymn the Father, Son, and Holy Spirit divine!\n\nWorthiest art Thou at all times to be sung\nWith undefiled tongue,\nSon of our God, Giver of Life, alone!\nTherefore in all the world, Thy glories, Lord, they own.","translit":"Phos hilaron","note":"The oldest Christian hymn still sung, at the lighting of the evening lamps; gentle at dusk at a bedside.","voice":"jenny","source":{"name":"The Hymn-Book of the Modern Church (1904), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/58619"},"rights":"pd","pd":"Greek Phos Hilaron, third century; John Keble translation 1834, Keble died 1866; public domain."},{"id":"cath-blessing-for-the-fortieth-day","title":"A Blessing for the Fortieth Day","by":"Grow With Grounded","year":2026,"trad":["orthodox"],"denom":["eastern"],"type":"blessing","occasion":["grief","funeral"],"text":"Forty days of tears and remembering.\nForty days of candles lit and prayers sung.\nMay the one we love rest among the saints, in a place of light.\nMay we who remain carry their memory with joy.\nMemory eternal.","note":"Grounded words for a family gathering on the fortieth day after a death, alongside the Church's own memorial.","voice":"brian","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."},{"id":"cath-blessing-for-an-icon-corner","title":"A Blessing for the Icon Corner","by":"Grow With Grounded","year":2026,"trad":["orthodox"],"denom":["eastern"],"type":"blessing","occasion":["home","daily"],"text":"Here, in the corner of our home, the saints keep watch with us.\nMay the lamp burn steady.\nMay our prayers rise like incense.\nMay every face that passes here find a little more peace.","note":"Grounded words for setting up or renewing a home's icon corner.","voice":"jenny","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."},{"id":"cath-ethiopia-stretch-out","title":"Ethiopia Shall Stretch Out Her Hands (Psalm 68)","by":"King James Version, Psalm 68:31 to 32","year":1611,"trad":["oriental","blackchurch"],"denom":["ethiopian"],"type":"scripture","occasion":["hope","celebration"],"text":"Princes shall come out of Egypt; Ethiopia shall soon stretch out her hands unto God.\nSing unto God, ye kingdoms of the earth; O sing praises unto the Lord; Selah:","note":"A verse treasured by the Ethiopian Orthodox Tewahedo Church and by the African American church as a promise for Africa's people.","voice":"jenny","source":{"name":"King James Bible (1611), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/10"},"rights":"pd","pd":"King James Version, 1611; public domain in the United States."},{"id":"cath-egypt-out-of-egypt","title":"Out of Egypt Have I Called My Son","by":"King James Version, Matthew 2:13 to 15","year":1611,"trad":["oriental"],"denom":["coptic"],"type":"scripture","occasion":["home","comfort"],"text":"And when they were departed, behold, the angel of the Lord appeareth to Joseph in a dream, saying, Arise, and take the young child and his mother, and flee into Egypt, and be thou there until I bring thee word: for Herod will seek the young child to destroy him.\nWhen he arose, he took the young child and his mother by night, and departed into Egypt:\nAnd was there until the death of Herod: that it might be fulfilled which was spoken of the Lord by the prophet, saying, Out of Egypt have I called my son.","note":"The Holy Family's flight into Egypt, dear to Coptic Christians, who keep the feast of its arrival each year; a comfort for families far from home.","voice":"brian","source":{"name":"King James Bible (1611), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/10"},"rights":"pd","pd":"King James Version, 1611; public domain in the United States."},{"id":"cath-blessed-be-egypt","title":"Blessed Be Egypt My People (Isaiah 19)","by":"King James Version, Isaiah 19:19, 25","year":1611,"trad":["oriental"],"denom":["coptic","syriac"],"type":"scripture","occasion":["blessing","hope"],"text":"In that day shall there be an altar to the Lord in the midst of the land of Egypt, and a pillar at the border thereof to the Lord.\n\nWhom the Lord of hosts shall bless, saying, Blessed be Egypt my people, and Assyria the work of my hands, and Israel mine inheritance.","note":"A blessing over Egypt and Assyria that Coptic and Syriac Christians hold close as their own.","voice":"jenny","source":{"name":"King James Bible (1611), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/10"},"rights":"pd","pd":"King James Version, 1611; public domain in the United States."},{"id":"cath-philip-and-the-ethiopian","title":"Philip and the Ethiopian (Acts 8)","by":"King James Version, Acts 8:35 to 39","year":1611,"trad":["oriental","christian"],"denom":["ethiopian"],"type":"scripture","occasion":["blessing","celebration"],"text":"Then Philip opened his mouth, and began at the same scripture, and preached unto him Jesus.\nAnd as they went on their way, they came unto a certain water: and the eunuch said, See, here is water; what doth hinder me to be baptized?\nAnd Philip said, If thou believest with all thine heart, thou mayest. And he answered and said, I believe that Jesus Christ is the Son of God.\nAnd he commanded the chariot to stand still: and they went down both into the water, both Philip and the eunuch; and he baptized him.\nAnd when they were come up out of the water, the Spirit of the Lord caught away Philip, that the eunuch saw him no more: and he went on his way rejoicing.","note":"The baptism of the Ethiopian official, honored by Ethiopian Christians as the first light of the Gospel in their land.","voice":"brian","source":{"name":"King James Bible (1611), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/10"},"rights":"pd","pd":"King James Version, 1611; public domain in the United States."},{"id":"cath-blessing-coptic","title":"A Blessing in the Coptic Spirit","by":"Grow With Grounded","year":2026,"trad":["oriental"],"denom":["coptic"],"type":"blessing","occasion":["blessing","comfort"],"text":"Blessed be the land that sheltered the Holy Family.\nMay the One who walked the roads of Egypt as a child walk beside you now.\nMay the faith of the martyrs make you brave,\nand the songs of the desert fathers and mothers keep your heart quiet and strong.\nPeace be with you.","note":"Grounded words to honor the Coptic Orthodox Church, used beside the family's own Agpeya prayers.","voice":"jenny","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."},{"id":"cath-blessing-armenian","title":"A Blessing in the Armenian Spirit","by":"Grow With Grounded","year":2026,"trad":["oriental"],"denom":["armenian"],"type":"blessing","occasion":["blessing","grief","hope"],"text":"You come from a people who kept the faith on mountain and in exile.\nMay the light of Saint Gregory the Illuminator shine on you.\nMay the cross carved in stone remind you that love outlasts every sorrow.\nMay the memory of your ancestors be a blessing, and your children's children sing.","note":"Grounded words to honor the Armenian Apostolic Church, used beside the family's own prayers and the priest's Hokehankist service.","voice":"brian","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."},{"id":"cath-blessing-ethiopian","title":"A Blessing in the Ethiopian Spirit","by":"Grow With Grounded","year":2026,"trad":["oriental"],"denom":["ethiopian","eritrean"],"type":"blessing","occasion":["blessing","celebration"],"text":"May you stretch out your hands to God, as your ancestors did.\nMay the light of the Meskel fire warm your home,\nand the long, patient prayers of your church hold you up.\nMay you rise each morning with gladness, and walk each day in peace.","note":"Grounded words to honor the Ethiopian and Eritrean Orthodox Tewahedo Churches.","voice":"jenny","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."},{"id":"cath-blessing-syriac","title":"A Blessing in the Syriac Spirit","by":"Grow With Grounded","year":2026,"trad":["oriental"],"denom":["syriac","malankara"],"type":"blessing","occasion":["blessing","peace"],"text":"Peace be with you, in the language Jesus spoke.\nMay the hymns of Saint Ephrem, the harp of the Spirit, sing in your heart.\nMay the light that rose in the East rise in you,\nand your home be a place where every guest is welcomed as Christ.","note":"Grounded words to honor the Syriac Orthodox and Malankara churches.","voice":"brian","source":{"name":"Grow With Grounded, written for the Grounded Readings Library (2026)","url":""},"rights":"grounded","pd":"Grounded's own words."},{"id":"cath-bcp-burial-sentences","title":"I Am the Resurrection and the Life","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"scripture","occasion":["funeral","hope"],"text":"I am the resurrection and the life, saith the Lord: he that believeth in me, though he were dead, yet shall he live: and whosoever liveth and believeth in me shall never die.\n\nI know that my Redeemer liveth, and that he shall stand at the latter day upon the earth. And though after my skin worms destroy this body, yet in my flesh shall I see God: whom I shall see for myself, and mine eyes shall behold, and not another.\n\nWe brought nothing into this world, and it is certain we can carry nothing out. The Lord gave, and the Lord hath taken away; blessed be the name of the Lord.","note":"The opening sentences of the Burial of the Dead, said as the body is carried into the church.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662 text, Cambridge printing with the Scottish Liturgy), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/29622"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States. John 11, Job 19, 1 Timothy 6, Job 1."},{"id":"cath-bcp-man-born-of-woman","title":"In the Midst of Life","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["funeral","grief"],"text":"Man that is born of a woman hath but a short time to live, and is full of misery. He cometh up, and is cut down, like a flower; he fleeth as it were a shadow, and never continueth in one stay.\n\nIn the midst of life we are in death: of whom may we seek for succour, but of thee, O Lord, who for our sins art justly displeased?\n\nYet, O Lord God most holy, O Lord most mighty, O holy and most merciful Saviour, deliver us not into the bitter pains of eternal death.\n\nThou knowest, Lord, the secrets of our hearts; shut not thy merciful ears to our prayer; but spare us, Lord most holy, O God most mighty, O holy and merciful Saviour, thou most worthy Judge eternal, suffer us not, at our last hour for any pains of death, to fall from thee.","note":"Said at the graveside as the body is made ready to be laid in the earth; some of the most famous words in English.","voice":"brian","source":{"name":"The Book of Common Prayer (1662 text, Cambridge printing with the Scottish Liturgy), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/29622"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-committal-1662","title":"Earth to Earth, Ashes to Ashes (1662)","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["funeral"],"text":"Forasmuch as it hath pleased Almighty God of his great mercy to take unto himself the soul of our dear brother here departed: we therefore commit his body to the ground; earth to earth, ashes to ashes, dust to dust; in sure and certain hope of the resurrection to eternal life, through our Lord Jesus Christ; who shall change our vile body, that it may be like unto his glorious body, according to the mighty working, whereby he is able to subdue all things to himself.","note":"The committal at the grave, said as earth is cast upon the coffin; say sister and her as fits.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662 text, Cambridge printing with the Scottish Liturgy), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/29622"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-committal-1928","title":"Unto Almighty God We Commend (1928)","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["funeral"],"text":"Unto Almighty God we commend the soul of our brother departed, and we commit his body to the ground; earth to earth, ashes to ashes, dust to dust; in sure and certain hope of the Resurrection unto eternal life, through our Lord Jesus Christ; at whose coming in glorious majesty to judge the world, the earth and the sea shall give up their dead; and the corruptible bodies of those who sleep in him shall be changed, and made like unto his own glorious body; according to the mighty working whereby he is able to subdue all things unto himself.","note":"The American committal at the graveside; also used for ashes and burial at sea with small changes.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States), Charles Wohlers's text","url":"http://justus.anglican.org/resources/bcp/1928/BCP_1928.htm"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-voice-from-heaven","title":"I Heard a Voice from Heaven","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"scripture","occasion":["funeral","grief","hope"],"text":"I heard a voice from heaven, saying unto me, Write: From henceforth blessed are the dead which die in the Lord: Even so, saith the Spirit, for they rest from their labours.","note":"Said after the committal; a quiet word that the work of a life is done and rest has come.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662 text, Cambridge printing with the Scottish Liturgy), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/29622"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States. Revelation 14:13."},{"id":"cath-bcp-spirits-of-those","title":"Almighty God, with Whom Still Live the Spirits","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["funeral","grief","gratitude"],"text":"Almighty God, with whom do live the spirits of those who depart hence in the Lord, and with whom the souls of the faithful, after they are delivered from the burden of the flesh, are in joy and felicity; We give thee hearty thanks for the good examples of all those thy servants, who, having finished their course in faith, do now rest from their labours. And we beseech thee, that we, with all those who are departed in the true faith of thy holy Name, may have our perfect consummation and bliss, both in body and soul, in thy eternal and everlasting glory; through Jesus Christ our Lord. Amen.","note":"A prayer of thanks for a faithful life, said at the burial.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States), Charles Wohlers's text","url":"http://justus.anglican.org/resources/bcp/1928/BCP_1928.htm"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-remember-thy-servant","title":"From Strength to Strength","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["funeral","grief","hope"],"text":"Remember thy servant, O Lord, according to the favour which thou bearest unto thy people,\nand grant that, increasing in knowledge and love of thee,\nhe may go from strength to strength, in the life of perfect service, in thy heavenly kingdom;\nthrough Jesus Christ our Lord, who liveth and reigneth with thee and the Holy Ghost ever, one God, world without end. Amen.","note":"A prayer that the one who has died keeps growing in love; say her as fits.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States), Charles Wohlers's text","url":"http://justus.anglican.org/resources/bcp/1928/BCP_1928.htm"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-mercies-cannot-be-numbered","title":"O God, Whose Mercies Cannot Be Numbered","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["funeral","grief"],"text":"O God, whose mercies cannot be numbered;\nAccept our prayers on behalf of the soul of thy servant departed,\nand grant him an entrance into the land of light and joy,\nin the fellowship of thy saints;\nthrough Jesus Christ our Lord. Amen.","note":"Said at the burial for the one who has died; say her as fits.","voice":"jenny","source":{"name":"The Book of Common Prayer (1928, United States), Charles Wohlers's text","url":"http://justus.anglican.org/resources/bcp/1928/BCP_1928.htm"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-days-without-end","title":"O God, Whose Days Are Without End","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["funeral","grief"],"text":"O God, whose days are without end, and whose mercies cannot be numbered;\nMake us, we beseech thee, deeply sensible of the shortness and uncertainty of human life;\nand let thy Holy Spirit lead us in holiness and righteousness, all our days:\nthat, when we shall have served thee in our generation,\nwe may be gathered unto our fathers, having the testimony of a good conscience;\nin the communion of the Catholic Church;\nin the confidence of a certain faith;\nin the comfort of a reasonable, religious, and holy hope;\nin favour with thee our God, and in perfect charity with the world.\nAll which we ask through Jesus Christ our Lord. Amen.","note":"A prayer for the living at a funeral, for a life well finished; drawn from Jeremy Taylor.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States), Charles Wohlers's text","url":"http://justus.anglican.org/resources/bcp/1928/BCP_1928.htm"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain. Adapted from Jeremy Taylor (died 1667)."},{"id":"cath-bcp-merciful-god-father","title":"O Merciful God, the Father of Our Lord","by":"The Book of Common Prayer (1662)","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"prayer","occasion":["funeral","hope"],"text":"O merciful God, the Father of our Lord Jesus Christ, who is the resurrection and the life; in whom whosoever believeth shall live, though he die; and whosoever liveth, and believeth in him, shall not die eternally; who also hath taught us (by his holy Apostle Saint Paul) not to be sorry, as men without hope, for them that sleep in him:\n\nWe meekly beseech thee, O Father, to raise us from the death of sin unto the life of righteousness; that, when we shall depart this life, we may rest in him, as our hope is this our brother doth; and that, at the general resurrection in the last day, we may be found acceptable in thy sight, and receive that blessing, which thy well-beloved Son shall then pronounce to all that love and fear thee, saying, Come, ye blessed children of my Father, receive the kingdom prepared for you from the beginning of the world:\n\nGrant this, we beseech thee, O merciful Father, through Jesus Christ, our Mediator and Redeemer. Amen.","note":"The closing collect of the burial service.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662 text, Cambridge printing with the Scottish Liturgy), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/29622"},"rights":"pd","pd":"The Book of Common Prayer, 1662; public domain in the United States."},{"id":"cath-bcp-god-of-spirits-1928","title":"Multiply to Those Who Rest","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"prayer","occasion":["funeral","grief","hope"],"text":"O Almighty God, the God of the spirits of all flesh, who by a voice from heaven didst proclaim, Blessed are the dead who die in the Lord;\nMultiply, we beseech thee, to those who rest in Jesus, the manifold blessings of thy love,\nthat the good work which thou didst begin in them may be perfected unto the day of Jesus Christ.\nAnd of thy mercy, O heavenly Father, vouchsafe that we, who now serve thee here on earth,\nmay at last, together with them, be found meet to be partakers of the inheritance of the saints in light;\nfor the sake of the same thy Son Jesus Christ our Lord. Amen.","note":"A prayer that joins the living and the dead in one hope.","voice":"brian","source":{"name":"The Book of Common Prayer (1928, United States), Charles Wohlers's text","url":"http://justus.anglican.org/resources/bcp/1928/BCP_1928.htm"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-god-of-peace","title":"The God of Peace","by":"The Book of Common Prayer (1928)","year":1928,"trad":["episcopal","christian"],"denom":["anglican","bcp1928"],"type":"blessing","occasion":["funeral","blessing","peace"],"text":"The God of peace, who brought again from the dead our Lord Jesus Christ, the great Shepherd of the sheep, through the blood of the everlasting covenant; Make you perfect in every good work to do his will, working in you that which is well pleasing in his sight; through Jesus Christ, to whom be glory for ever and ever. Amen.","note":"The blessing that closes the burial service, from Hebrews 13.","voice":"jenny","source":{"name":"The Book of Common Prayer (1928, United States), Charles Wohlers's text","url":"http://justus.anglican.org/resources/bcp/1928/BCP_1928.htm"},"rights":"pd","pd":"The Book of Common Prayer of the Episcopal Church, 1928; public domain."},{"id":"cath-bcp-psalm-90","title":"Lord, Thou Hast Been Our Refuge (Psalm 90)","by":"The Book of Common Prayer (1662), Coverdale Psalter","tr":"Miles Coverdale","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"scripture","occasion":["funeral","grief"],"text":"Lord, thou hast been our refuge: from one generation to another.\nBefore the mountains were brought forth, or ever the earth and the world were made: thou art God from everlasting, and world without end.\nThou turnest man to destruction: again thou sayest, Come again, ye children of men.\nFor a thousand years in thy sight are but as yesterday: seeing that is past as a watch in the night.\nAs soon as thou scatterest them they are even as a sleep: and fade away suddenly like the grass.\nIn the morning it is green, and groweth up: but in the evening it is cut down, dried up, and withered.\n\nThe days of our age are threescore years and ten; and though men be so strong that they come to fourscore years: yet is their strength then but labour and sorrow; so soon passeth it away, and we are gone.\n\nSo teach us to number our days: that we may apply our hearts unto wisdom.","note":"One of the two psalms of the burial service, in the beloved Coverdale wording.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662 text, Cambridge printing with the Scottish Liturgy), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/29622"},"rights":"pd","pd":"Miles Coverdale translation, 1535, as printed in the Book of Common Prayer, 1662; public domain."},{"id":"cath-bcp-psalm-23","title":"The Lord Is My Shepherd (Coverdale)","by":"The Book of Common Prayer (1662), Coverdale Psalter","tr":"Miles Coverdale","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"scripture","occasion":["funeral","comfort","dying"],"text":"The Lord is my shepherd: therefore can I lack nothing.\nHe shall feed me in a green pasture: and lead me forth beside the waters of comfort.\nHe shall convert my soul: and bring me forth in the paths of righteousness, for his Name's sake.\nYea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff comfort me.\nThou shalt prepare a table before me against them that trouble me: thou hast anointed my head with oil, and my cup shall be full.\nBut thy loving-kindness and mercy shall follow me all the days of my life: and I will dwell in the house of the Lord for ever.","note":"Psalm 23 as Anglicans have prayed it for nearly five hundred years: beside the waters of comfort.","voice":"brian","source":{"name":"The Book of Common Prayer (1662 text, Cambridge printing with the Scottish Liturgy), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/29622"},"rights":"pd","pd":"Miles Coverdale translation, 1535, as printed in the Book of Common Prayer, 1662; public domain."},{"id":"cath-bcp-psalm-121","title":"I Will Lift Up Mine Eyes (Coverdale)","by":"The Book of Common Prayer (1662), Coverdale Psalter","tr":"Miles Coverdale","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"scripture","occasion":["comfort","dying","blessing"],"text":"I will lift up mine eyes unto the hills: from whence cometh my help.\nMy help cometh even from the Lord: who hath made heaven and earth.\nHe will not suffer thy foot to be moved: and he that keepeth thee will not sleep.\nBehold, he that keepeth Israel: shall neither slumber nor sleep.\nThe Lord himself is thy keeper: the Lord is thy defence upon thy right hand;\nSo that the sun shall not burn thee by day: neither the moon by night.\nThe Lord shall preserve thee from all evil: yea, it is even he that shall keep thy soul.\nThe Lord shall preserve thy going out, and thy coming in: from this time forth for evermore.","note":"The traveler's psalm, prayed for journeys and for the last journey home.","voice":"jenny","source":{"name":"The Book of Common Prayer (1662 text, Cambridge printing with the Scottish Liturgy), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/29622"},"rights":"pd","pd":"Miles Coverdale translation, 1535, as printed in the Book of Common Prayer, 1662; public domain."},{"id":"cath-bcp-psalm-100","title":"O Be Joyful in the Lord (Psalm 100)","by":"The Book of Common Prayer (1662), Coverdale Psalter","tr":"Miles Coverdale","year":1662,"trad":["episcopal","christian"],"denom":["anglican","bcp1662"],"type":"scripture","occasion":["gratitude","celebration","morning"],"text":"O be joyful in the Lord, all ye lands: serve the Lord with gladness, and come before his presence with a song.\nBe ye sure that the Lord he is God: it is he that hath made us, and not we ourselves; we are his people, and the sheep of his pasture.\nO go your way into his gates with thanksgiving, and into his courts with praise: be thankful unto him, and speak good of his Name.\nFor the Lord is gracious, his mercy is everlasting: and his truth endureth from generation to generation.","note":"The Jubilate, sung at Morning Prayer; a glad psalm for a celebration of life.","voice":"brian","source":{"name":"The Book of Common Prayer (1662 text, Cambridge printing with the Scottish Liturgy), Project Gutenberg","url":"https://www.gutenberg.org/ebooks/29622"},"rights":"pd","pd":"Miles Coverdale translation, 1535, as printed in the Book of Common Prayer, 1662; public domain."}];
